import{_ as n,o as h,c as o,a3 as d}from"./chunks/framework.DX_KL3e0.js";const s=JSON.parse('{"title":"Phân quyền & vai trò","description":"","frontmatter":{},"headers":[],"relativePath":"bat-dau/phan-quyen.md","filePath":"bat-dau/phan-quyen.md","lastUpdated":1783009205000}'),i={name:"bat-dau/phan-quyen.md"};function e(a,t,c,r,g,u){return h(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="phan-quyen-vai-tro" tabindex="-1">Phân quyền &amp; vai trò <a class="header-anchor" href="#phan-quyen-vai-tro" aria-label="Permalink to &quot;Phân quyền &amp; vai trò&quot;">​</a></h1><p>Hệ thống dùng cơ chế phân quyền <strong>2 tầng</strong>: vai trò (role) quyết định mặc định, và <strong>phân quyền chi tiết theo module</strong> có thể tinh chỉnh cho từng người dùng.</p><h2 id="_4-vai-tro" tabindex="-1">4 vai trò <a class="header-anchor" href="#_4-vai-tro" aria-label="Permalink to &quot;4 vai trò&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Vai trò</th><th>Mã</th><th>Phạm vi dữ liệu</th><th>Đặc trưng</th></tr></thead><tbody><tr><td><strong>Super Admin</strong></td><td><code>super_admin</code></td><td>Toàn hệ thống</td><td>Thấy &amp; làm mọi thứ, kể cả <a href="/help/quan-tri/cau-hinh-ticket.html">Cấu hình Ticket</a>.</td></tr><tr><td><strong>Quản trị viên</strong></td><td><code>admin</code></td><td>Theo công ty được gán</td><td>Gần như toàn quyền, <strong>không có quyền Xóa</strong> ở phần lớn module; <strong>Cài đặt</strong> chỉ xem.</td></tr><tr><td><strong>Quản lý</strong></td><td><code>manager</code></td><td>Theo công ty được gán</td><td>Quản lý cấp phòng; <strong>Người dùng / Tổ chức / Cài đặt</strong> chỉ xem; duyệt bù công, tăng ca, nghỉ phép và xem bảng công / chuyên cần của cấp dưới.</td></tr><tr><td><strong>Người dùng</strong></td><td><code>user</code></td><td>Chỉ dữ liệu cá nhân</td><td>Tự phục vụ: ticket, đặt phòng, chấm công, hồ sơ cá nhân, tra cứu.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Phạm vi dữ liệu (Tầng 2)</p><p>Ngoài việc &quot;thấy module nào&quot;, hệ thống còn lọc <strong>dữ liệu</strong>: Super Admin thấy toàn bộ; Admin/Quản lý thấy theo công ty được gán; Người dùng chỉ thấy dữ liệu của chính mình.</p></div><h2 id="quyen-mac-đinh-theo-vai-tro" tabindex="-1">Quyền mặc định theo vai trò <a class="header-anchor" href="#quyen-mac-đinh-theo-vai-tro" aria-label="Permalink to &quot;Quyền mặc định theo vai trò&quot;">​</a></h2><p>Khi tạo người dùng, hệ thống gán sẵn bộ quyền theo vai trò:</p><ul><li><strong>Super Admin</strong> — tất cả hành động trên mọi module.</li><li><strong>Admin</strong> — mọi hành động <strong>trừ <code>Xóa</code></strong>; riêng <strong>Cài đặt</strong> chỉ <code>Xem</code>.</li><li><strong>Quản lý</strong> — như Admin nhưng <strong>Người dùng, Tổ chức, Cài đặt</strong> chỉ <code>Xem</code>.</li><li><strong>Người dùng</strong> — chỉ <code>Xem</code> ở những module có hành động <code>Xem</code>.</li></ul><h2 id="cac-hanh-đong-permission-action" tabindex="-1">Các hành động (permission action) <a class="header-anchor" href="#cac-hanh-đong-permission-action" aria-label="Permalink to &quot;Các hành động (permission action)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hành động</th><th>Ý nghĩa</th></tr></thead><tbody><tr><td><code>Xem</code> (view)</td><td>Xem dữ liệu của module</td></tr><tr><td><code>Thêm</code> (create)</td><td>Tạo bản ghi mới</td></tr><tr><td><code>Sửa</code> (edit)</td><td>Chỉnh sửa bản ghi</td></tr><tr><td><code>Xóa</code> (delete)</td><td>Xóa bản ghi</td></tr><tr><td><code>Phê duyệt</code> (approve)</td><td>Duyệt/đóng/xác nhận</td></tr><tr><td><code>Xuất dữ liệu</code> (export)</td><td>Xuất file (Excel…)</td></tr><tr><td><code>Nhận thông báo</code> (notify)</td><td>Nhận cảnh báo/nhắc liên quan</td></tr></tbody></table><h2 id="module-luon-hien-thi-cho-moi-nguoi-đa-đang-nhap" tabindex="-1">Module luôn hiển thị cho mọi người đã đăng nhập <a class="header-anchor" href="#module-luon-hien-thi-cho-moi-nguoi-đa-đang-nhap" aria-label="Permalink to &quot;Module luôn hiển thị cho mọi người đã đăng nhập&quot;">​</a></h2><p>Một số module phục vụ tự thân nên <strong>luôn xuất hiện</strong> bất kể phân quyền chi tiết:</p><ul><li><strong>Tra Cứu</strong> (<code>/tra-cuu</code>)</li><li><strong>Dữ Liệu Chấm Công</strong> (<code>/tra-cuu/du-lieu-cong</code>)</li><li><strong>Hợp đồng &amp; Hồ sơ</strong> của tôi (<code>/ho-so-cua-toi</code>)</li><li><strong>Chữ Ký Email</strong> (<code>/email-signature</code>) — mọi người đều có thể tạo chữ ký email cá nhân</li></ul><h2 id="tinh-chinh-quyen-cho-tung-nguoi" tabindex="-1">Tinh chỉnh quyền cho từng người <a class="header-anchor" href="#tinh-chinh-quyen-cho-tung-nguoi" aria-label="Permalink to &quot;Tinh chỉnh quyền cho từng người&quot;">​</a></h2><p>Admin/Super Admin có thể chỉnh quyền chi tiết cho từng người dùng tại <strong>Người Dùng → chọn người → tab Phân Quyền</strong>. Xem <a href="/help/quan-tri/nguoi-dung.html">Người dùng &amp; phân quyền</a>.</p><div class="warning custom-block"><p class="custom-block-title">Lưu ý</p><p>Một số module <strong>con</strong> (ví dụ các trang trong Quản lý Tài sản hay Chấm công) có thể <strong>kế thừa quyền của module mẹ</strong> nếu chưa được cấu hình riêng — để tránh khóa nhầm người dùng cũ khi hệ thống bổ sung module mới.</p></div>',16)])])}const m=n(i,[["render",e]]);export{s as __pageData,m as default};
